<template><view class="page"><SearchBar v-model="query" placeholder="通道名称或编号" @search="reload"/><view class="list"><view v-for="item in items" :key="item.channelDeviceId||item.deviceDbId" class="card" @click="play(item)"><view class="card__top"><text class="card__title">{{ item.name || item.channelDeviceId }}</text><StatusBadge :value="item.status"/></view><text class="card__meta">通道：{{ item.channelDeviceId || item.deviceDbId }}\n点击进入实时预览</text></view><EmptyState v-if="!loading&&!items.length" title="暂无通道"/><view v-if="items.length" class="footer">{{ loading?'加载中…':finished?'没有更多了':'上拉加载更多' }}</view></view></view></template>
<script setup lang="ts">
import {ref} from 'vue'; import {onLoad,onPullDownRefresh,onReachBottom} from '@dcloudio/uni-app'; import SearchBar from '@/components/SearchBar.vue'; import EmptyState from '@/components/EmptyState.vue'; import StatusBadge from '@/components/StatusBadge.vue'; import {queryChannels,type Channel} from '@/api/device'; import {showRequestError} from '@/utils/request'
const deviceId=ref('');const query=ref('');const items=ref<Channel[]>([]);const page=ref(1);const loading=ref(false);const finished=ref(false)
async function load(reset=false){if(!deviceId.value||loading.value||(!reset&&finished.value))return;if(reset){page.value=1;finished.value=false}loading.value=true;try{const r=await queryChannels(deviceId.value,{page:page.value,count:20,query:query.value,online:'',channelType:'',catalogUnderDevice:true});const list=r.list||r.items||[];items.value=reset?list:[...items.value,...list];finished.value=list.length<20;page.value++}catch(e){showRequestError(e)}finally{loading.value=false;uni.stopPullDownRefresh()}}
function reload(){load(true)} function play(item:Channel){const channelId=item.channelDeviceId||item.deviceDbId;if(channelId)uni.navigateTo({url:`/pages/player/index?deviceId=${encodeURIComponent(deviceId.value)}&channelId=${encodeURIComponent(channelId)}&name=${encodeURIComponent(item.name||channelId)}`})}
onLoad((q)=>{deviceId.value=String(q?.deviceId||'');if(q?.name)uni.setNavigationBarTitle({title:String(q.name)});load(true)});onPullDownRefresh(reload);onReachBottom(()=>load())
</script><style lang="scss" scoped>@use '@/styles/list.scss';</style>
